<style>
  .ca3-page{--ca3-primary:#087f9f;--ca3-dark:#0b3c5d;--ca3-muted:#6f8797;--ca3-border:#d7e5eb;--ca3-soft:#f2f9fb;padding:14px;color:#173f57;background:#f6fafc}
  .ca3-hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 22px;margin-bottom:14px;border-radius:16px;color:#fff;background:linear-gradient(118deg,#07527b 0%,#078eae 58%,#18a99e 100%);box-shadow:0 10px 28px rgba(14,91,119,.16)}
  .ca3-hero:after{content:"";position:absolute;right:-48px;top:-88px;width:250px;height:250px;border:34px solid rgba(255,255,255,.08);border-radius:50%}
  .ca3-hero__main,.ca3-patient{position:relative;z-index:1;display:flex;align-items:center;gap:13px;min-width:0}
  .ca3-hero__icon{display:grid;place-items:center;flex:0 0 52px;width:52px;height:52px;border:1px solid rgba(255,255,255,.32);border-radius:13px;background:rgba(255,255,255,.13);font-size:22px}
  .ca3-eyebrow{font-size:10px;font-weight:900;letter-spacing:1.1px}.ca3-hero h1{margin:2px 0;font-size:23px;font-weight:900;line-height:1.15}.ca3-hero p{margin:0;font-size:12px;opacity:.94}
  .ca3-hero__actions{position:relative;z-index:1;display:flex;gap:8px;flex-shrink:0}.ca3-hero .btn{padding:8px 13px;border-radius:9px;font-size:11px;font-weight:800;box-shadow:none}

  .ca3-summary{display:grid;grid-template-columns:1.35fr repeat(3,1fr);gap:10px;margin-bottom:14px}
  .ca3-summary__patient,.ca3-summary__item{min-width:0;min-height:76px;padding:14px 15px;border:1px solid var(--ca3-border);border-radius:12px;background:#fff;box-shadow:0 4px 14px rgba(28,80,105,.05)}
  .ca3-summary__item{display:flex;align-items:center;gap:11px}.ca3-avatar{display:grid;place-items:center;flex:0 0 42px;width:42px;height:42px;border-radius:11px;color:#087e9d;background:#daf4f6;font-size:13px;font-weight:900}
  .ca3-summary__icon{display:grid;place-items:center;flex:0 0 35px;width:35px;height:35px;border-radius:10px;color:#0787a7;background:#e4f5f8;font-size:14px}.ca3-summary__item>div:last-child,.ca3-patient>div:last-child{min-width:0}
  .ca3-summary strong{display:block;overflow:hidden;color:var(--ca3-dark);font-size:12px;line-height:1.35;text-overflow:ellipsis;white-space:nowrap}.ca3-summary span{display:block;margin-bottom:3px;color:var(--ca3-muted);font-size:9.5px;font-weight:900;letter-spacing:.25px;text-transform:uppercase}.ca3-summary small{display:block;overflow:hidden;margin-top:4px;color:#7891a1;font-size:10px;line-height:1.3;text-overflow:ellipsis;white-space:nowrap}

  .ca3-alert{margin-bottom:12px;border:0;border-radius:11px;font-size:12px;box-shadow:0 4px 12px rgba(31,78,100,.05)}.ca3-card{overflow:hidden;margin-bottom:14px;border:1px solid var(--ca3-border);border-radius:14px;background:#fff;box-shadow:0 5px 18px rgba(28,79,103,.055)}
  .ca3-card__head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 15px;border-bottom:1px solid #dce9ee;background:var(--ca3-soft)}.ca3-title{display:flex;align-items:center;gap:10px;min-width:0}.ca3-title>i{display:grid;place-items:center;flex:0 0 34px;width:34px;height:34px;border-radius:9px;color:#0789ac;background:#d8f1f6}.ca3-title h2{margin:0;color:var(--ca3-dark);font-size:14px;font-weight:900;line-height:1.25}.ca3-title p{margin:2px 0 0;color:#718b9d;font-size:10.5px;line-height:1.35}.ca3-card__body{padding:16px}.co-count{flex-shrink:0}

  .ca3-actions{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.ca3-action{display:flex;align-items:center;gap:11px;min-height:74px;padding:12px;border:1px solid #d6e6ec;border-radius:11px;color:#164764;background:#fff;transition:border-color .16s,background .16s,transform .16s,box-shadow .16s}.ca3-action:hover{color:#087ea0;border-color:#8ccede;background:#f2fbfd;text-decoration:none;transform:translateY(-2px);box-shadow:0 6px 14px rgba(8,126,160,.09)}.ca3-action>i{display:grid;place-items:center;flex:0 0 38px;width:38px;height:38px;border-radius:10px;color:#0789aa;background:#ddf4f7;font-size:14px}.ca3-action strong{display:block;font-size:11.5px;line-height:1.3}.ca3-action small{display:block;margin-top:3px;color:#7891a0;font-size:9.5px;line-height:1.3}.ca3-action.is-disabled{opacity:.5;pointer-events:none;background:#f6f9fa}

  .ca3-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 10px}.ca3-form-divider{grid-column:1/-1;display:flex;align-items:center;gap:9px;padding:9px 11px;margin-top:4px;border-left:3px solid #11a2b5;border-radius:0 8px 8px 0;background:#f3fafc}.ca3-form-divider:first-child{margin-top:0}.ca3-form-divider>i{display:grid;place-items:center;width:28px;height:28px;border-radius:8px;color:#078ba9;background:#ddf3f6;font-size:12px}.ca3-form-divider strong{display:block;color:#16445f;font-size:11px}.ca3-form-divider small{display:block;margin-top:1px;color:#78909e;font-size:9.5px}.ca3-field.ca3-span-2{grid-column:span 2}.ca3-field.ca3-span-4{grid-column:span 4}
  .ca3-field label{display:block;margin-bottom:5px;color:#294f66;font-size:9.5px;font-weight:900;letter-spacing:.12px;text-transform:uppercase}.ca3-field .form-control{min-height:38px;border-color:#c8dce5;border-radius:8px;color:#21475e;background:#fff;font-size:12px;box-shadow:none}.ca3-field textarea.form-control{height:auto;min-height:76px;padding-top:9px;resize:vertical}.ca3-field .form-control:focus{border-color:#0b96b8;box-shadow:0 0 0 3px rgba(11,150,184,.1)}.ca3-field .form-control[readonly]{color:#527083;background:#f4f8fa}.ca3-form__footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;border-top:1px solid #dce9ee;background:#fbfdfe}.ca3-form__footer small{color:#7891a1;font-size:10px}.ca3-form__footer .btn{padding:8px 15px;border-radius:8px;font-size:11px;font-weight:800}

  .ca3-modules{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ca3-module{overflow:hidden;border:1px solid #d5e5eb;border-radius:12px;background:#fff;transition:border-color .16s,box-shadow .16s}.ca3-module:hover{border-color:#b9d8e2;box-shadow:0 5px 14px rgba(23,87,113,.06)}.ca3-module__head{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;background:#f2f9fb}.ca3-module__head strong{color:#113f5c;font-size:12px}.ca3-module__head span{min-width:24px;padding:4px 7px;border-radius:15px;color:#087c9e;background:#dff4f7;font-size:9px;font-weight:900;text-align:center}.ca3-module__body{padding:8px 13px}.ca3-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #e6eef2}.ca3-row:last-child{border-bottom:0}.ca3-row>div{min-width:0}.ca3-row strong{display:block;overflow:hidden;color:#244d66;font-size:11px;line-height:1.35;text-overflow:ellipsis}.ca3-row small{display:block;margin-top:2px;color:#7891a1;font-size:9.5px;line-height:1.35}.ca3-empty{padding:22px 12px;text-align:center;color:#8299a8;font-size:11px}.ca3-module__foot{padding:9px 13px;border-top:1px solid #e2ecef;background:#fbfdfe}.ca3-module__foot .btn,.ca3-row .btn{border-radius:7px;font-size:10px;font-weight:800}
  .ca3-field .select2-container{width:100%!important}.ca3-field .select2-container--bootstrap4 .select2-selection--multiple{min-height:38px;border-color:#c8dce5;border-radius:8px;background:#fff}.ca3-field .select2-container--bootstrap4.select2-container--focus .select2-selection{border-color:#0b96b8;box-shadow:0 0 0 3px rgba(11,150,184,.1)}.ca3-field .select2-container--bootstrap4 .select2-selection--multiple .select2-selection__choice{margin-top:5px;padding:3px 7px;border:0;border-radius:14px;color:#11617a;background:#dff3f7;font-size:10px;font-weight:700}.ca3-field .select2-container--bootstrap4 .select2-selection--multiple .select2-selection__choice__remove{margin-right:5px;color:#4c7b8c}

  @media(max-width:1180px){.ca3-summary{grid-template-columns:repeat(2,1fr)}.ca3-summary__patient{grid-column:span 2}.ca3-actions{grid-template-columns:repeat(3,1fr)}}
  @media(max-width:900px){.ca3-grid{grid-template-columns:repeat(2,1fr)}.ca3-field.ca3-span-4{grid-column:span 2}.ca3-actions{grid-template-columns:repeat(2,1fr)}}
  @media(max-width:720px){.ca3-page{padding:9px}.ca3-hero{align-items:flex-start;flex-direction:column;padding:17px}.ca3-hero__actions{width:100%;flex-wrap:wrap}.ca3-hero__actions .btn{flex:1}.ca3-summary,.ca3-grid,.ca3-actions,.ca3-modules{grid-template-columns:1fr}.ca3-summary__patient,.ca3-field.ca3-span-2,.ca3-field.ca3-span-4{grid-column:span 1}.ca3-card__head,.ca3-form__footer{align-items:flex-start;flex-direction:column}.ca3-card__body{padding:12px}.ca3-form__footer .btn{width:100%}}
</style>
